866	    private function cheapestQueueableDefence(PlanetService $planet, ?DefenseNeed $need, bool $aheadOfEconomy = true): ?QueueableUnit
867	    {
868	        $best = null;
869	        $bestPrice = INF;
870	
871	        foreach (ObjectService::getDefenseObjects() as $unit) {
872	            if (! $unit instanceof UnitObject || ! $this->requirementsMet($planet, $unit)) {
873	                continue;
874	            }
875	
876	            $price = $this->metalEquivalent(ObjectService::getObjectRawPrice($unit->machine_name));
877	            if ($price <= 0.0 || $price >= $bestPrice) {
878	                continue;
879	            }
880	
881	            $best = $unit;
882	            $bestPrice = $price;
883	        }
884	
885	        if ($best === null) {
886	            return null;
887	        }
888	
889	        $amount = min(
890	            $this->affordable($planet, $best),
891	            max(self::FIRST_CARGO_AMOUNT, (int) ceil(($need?->defenceValue ?? 0.0) / $bestPrice))
892	        );
893	
894	        // The host refuses an order it cannot pay for whole, so a planet holding less than one unit's
895	        // price is left to a later login rather than sent a batch that creates no queue row.
896	        if ($amount < self::FIRST_CARGO_AMOUNT) {
897	            return null;
898	        }
899	
900	        return $this->unit($planet, $best, 'role:defense:standing:'.$best->machine_name, $amount, $aheadOfEconomy);
