    expect(app(DefenseNeedEvaluator::class)->standingUnits(app(PlanetServiceFactory::class)->make($this->currentPlanetId, true)))
        ->toBe(20, 'the login stacked wall on the planet that already holds one; ' . $situation->account());
});

